/**
 * API 클라이언트 서비스
 * 백엔드 API와 통신하는 중앙화된 서비스
 */

import { Test, TestList, Result, ResultList, Question, UserPerformance, UserHistory, UserProfile, AdminUser, AdminQuestion, AdminStatistics, Vocabulary, VocabularyReview, ReviewStatistics, DailyGoal, DailyGoalWithStatistics } from '../types/api';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';
const API_PREFIX = '/api/v1';

/**
 * API 응답 타입
 */
interface ApiResponse<T> {
  success: boolean;
  data: T;
  message?: string;
  errors?: string[];
}

/**
 * API 에러 클래스
 */
export class ApiError extends Error {
  constructor(
    public status: number,
    public message: string,
    public errors?: string[]
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

/**
 * API 요청 옵션
 */
interface RequestOptions extends RequestInit {
  requireAuth?: boolean;
}

/**
 * 기본 fetch 래퍼 함수
 */
async function fetchApi<T>(
  endpoint: string,
  options: RequestOptions = {}
): Promise<T> {
  const { requireAuth = true, ...fetchOptions } = options;

  const url = `${API_BASE_URL}${API_PREFIX}${endpoint}`;

  const headers: HeadersInit = {
    'Content-Type': 'application/json',
    ...fetchOptions.headers,
  };

  // 세션 쿠키는 자동으로 전송됨 (credentials: 'include' 필요)
  const config: RequestInit = {
    ...fetchOptions,
    headers,
    credentials: 'include', // 쿠키 포함
  };

  try {
    const response = await fetch(url, config);

    // 응답이 JSON이 아닌 경우 처리
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      if (response.ok) {
        return {} as T;
      }
      throw new ApiError(
        response.status,
        `Unexpected content type: ${contentType}`
      );
    }

    let payload: unknown;
    try {
      payload = await response.json();
    } catch (jsonError) {
      // JSON 파싱 실패 시
      if (!response.ok) {
        throw new ApiError(
          response.status,
          `HTTP ${response.status} ${response.statusText}`
        );
      }
      throw new ApiError(500, '응답 파싱 중 오류가 발생했습니다.');
    }

    if (!response.ok) {
      // 백엔드가 ApiResponse 형태가 아닌 FastAPI 기본 에러 형태({"detail": ...})를
      // 반환하는 경우도 메시지를 최대한 살립니다.
      if (payload && typeof payload === 'object') {
        const anyPayload = payload as any;

        // detail이 배열인 경우 (FastAPI validation error)
        let message: string;
        if (anyPayload.message) {
          message = anyPayload.message;
        } else if (Array.isArray(anyPayload.detail)) {
          // validation error 배열에서 메시지 추출
          message = anyPayload.detail
            .map((err: any) => {
              if (typeof err === 'string') {
                return err;
              }
              if (err && typeof err === 'object' && err.msg) {
                return err.msg;
              }
              return JSON.stringify(err);
            })
            .join(', ');
        } else if (anyPayload.detail) {
          // detail이 문자열이거나 단일 객체인 경우
          if (typeof anyPayload.detail === 'string') {
            message = anyPayload.detail;
          } else if (typeof anyPayload.detail === 'object' && anyPayload.detail.msg) {
            message = anyPayload.detail.msg;
          } else {
            message = JSON.stringify(anyPayload.detail);
          }
        } else {
          message = `HTTP ${response.status} ${response.statusText}`;
        }

        throw new ApiError(response.status, message, anyPayload.errors);
      }
      throw new ApiError(
        response.status,
        `HTTP ${response.status} ${response.statusText}`
      );
    }

    // 성공 응답도 백엔드에 따라 래핑(ApiResponse) 여부가 다를 수 있어 유연하게 처리합니다.
    if (payload && typeof payload === 'object') {
      const anyPayload = payload as any;
      if ('success' in anyPayload && 'data' in anyPayload) {
        return anyPayload.data as T;
      }
    }
    return payload as T;
  } catch (error) {
    if (error instanceof ApiError) {
      throw error;
    }
    if (error instanceof TypeError && error.message === 'Failed to fetch') {
      throw new ApiError(0, '네트워크 오류가 발생했습니다. 서버에 연결할 수 없습니다.');
    }
    // 더 자세한 에러 정보 로깅
    console.error('API 요청 중 예상치 못한 오류:', error);
    if (error instanceof Error) {
      throw new ApiError(500, `알 수 없는 오류가 발생했습니다: ${error.message}`);
    }
    throw new ApiError(500, '알 수 없는 오류가 발생했습니다.');
  }
}

